// Normalizes input meal data from different ingestion sources (Webhook payload, Excel rows, or JSON files)
const items = $input.all();
const results = [];

for (const item of items) {
  let raw = item.json;

  // Support nested body if incoming from webhook
  if (raw.body && typeof raw.body === 'object') {
    raw = Array.isArray(raw.body) ? raw.body : (raw.body.meals || [raw.body]);
  }

  const rawArray = Array.isArray(raw) ? raw : [raw];

  for (const meal of rawArray) {
    let nameEn = (meal.name?.en || meal.name || meal.dish_name || meal.dishName || meal.Dish || '').trim();
    let nameHi = (meal.name?.hi || meal.name_hindi || meal.dish_name_hi || '').trim();

    // Handle placeholder names from Phase 1
    if (/^(north|south|east|west)\s*meal\s*\d+/i.test(nameEn) && meal.suggested_authentic_name) {
      nameEn = meal.suggested_authentic_name.trim();
    }

    // Generate kebab-case unique ID slug
    const baseSlug = nameEn
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '');

    const id = meal.id || baseSlug || `meal-${Date.now()}-${Math.floor(Math.random()*1000)}`;

    // Normalize Region
    let region = (meal.region || meal.Region || 'north').toLowerCase().trim();
    if (!['north', 'south', 'east', 'west'].includes(region)) {
      region = 'north';
    }

    // Normalize Meal Time
    let time = (meal.time || meal.meal_time || meal.mealTime || meal.MealTime || 'lunch').toLowerCase().trim();
    if (!['breakfast', 'lunch', 'dinner', 'snack'].includes(time)) {
      time = 'lunch';
    }

    // Extract & Parse Macros
    const protein = parseFloat(meal.protein ?? meal.macros?.protein ?? meal.Protein_g ?? 0) || 0;
    const carbohydrate = parseFloat(meal.carbs ?? meal.carbohydrate ?? meal.macros?.carbohydrate ?? meal.Carbs_g ?? 0) || 0;
    const fat = parseFloat(meal.fat ?? meal.macros?.fat ?? meal.Fat_g ?? 0) || 0;
    const fibre = parseFloat(meal.fiber ?? meal.fibre ?? meal.macros?.fibre ?? meal.Fiber_g ?? 0) || 0;

    // Extract or calculate calories
    let kcal = parseInt(meal.kcal ?? meal.calories ?? meal.Calories ?? meal.Energy_kcal ?? 0, 10);
    if (!kcal || kcal <= 0) {
      kcal = Math.round((protein * 4) + (carbohydrate * 4) + (fat * 9));
    }

    // Normalize Category
    let category = (meal.category || meal.diet_category || meal.Category || 'veg').toLowerCase().trim();
    if (category.includes('non') || category === 'nv' || category === 'non-veg') {
      category = 'nonveg';
    } else {
      category = 'veg';
    }

    // Extract raw tags
    let tags = Array.isArray(meal.tags) ? [...meal.tags] : [];

    results.push({
      json: {
        id,
        nameEn,
        nameHi,
        region,
        time,
        category,
        tags,
        kcal,
        macros: {
          protein: Math.round(protein * 10) / 10,
          carbohydrate: Math.round(carbohydrate * 10) / 10,
          fat: Math.round(fat * 10) / 10,
          fibre: Math.round(fibre * 10) / 10
        },
        meat_type: meal.meat_type || meal.meatType || '',
        ingredients: Array.isArray(meal.ingredients) ? meal.ingredients : [],
        noteEn: meal.note?.en || meal.note || meal.description || '',
        noteHi: meal.note?.hi || meal.description_hi || '',
        source: meal.source || 'n8n_pipeline',
        photo: meal.photo || undefined
      }
    });
  }
}

return results;

// Quality Assurance & Nutrition Verification Engine (Implements Poshan Phases 3 & 4 Rules)
const items = $input.all();
const validatedMeals = [];
const auditLog = [];

// Common Indian dish dictionary for bilingual fallback
const HINDI_DISH_MAP = {
  'poha': 'पोहा',
  'aloo paratha': 'आलू पराठा',
  'rajma chawal': 'राजमा चावल',
  'chole': 'छोले',
  'palak paneer': 'पालक पनीर',
  'paneer tikka': 'पनीर टिक्का',
  'paneer tikka power bowl': 'पनीर टिक्का पावर बाउल',
  'idli': 'इडली',
  'masala dosa': 'मसाला डोसा',
  'sambar': 'सांबर',
  'rasam': 'रसम',
  'curd rice': 'दही चावल',
  'chettinad fish curry': 'चेट्टीनाड मछली करी',
  'chettinad fish curry with brown rice': 'ब्राउन राइस के साथ चेट्टीनाड मछली करी',
  'machher jhol': 'माछेर झोल',
  'litti chokha': 'लिट्टी चोखा',
  'dhokla': 'ढोकला',
  'thepla': 'थेपला',
  'khichdi': 'खिचड़ी',
  'moong dal chilla with mint chutney': 'पुदीना चटनी के साथ मूंग दाल चीला',
  'sprouted moong & paneer chaat': 'अंकुरित मूंग और पनीर चाट',
  'gulab jamun': 'गुलाब जामुन'
};

for (const item of items) {
  const meal = item.json;
  const logEntries = [];

  // 1. Placeholder Name Detection & Cleanup
  if (/^(north|south|east|west)\s*meal/i.test(meal.nameEn)) {
    logEntries.push(`WARN: Generic placeholder name detected: ${meal.nameEn}`);
  }

  // 2. Hindi Translation Enrichment
  if (!meal.nameHi || meal.nameHi === '') {
    const lower = meal.nameEn.toLowerCase();
    if (HINDI_DISH_MAP[lower]) {
      meal.nameHi = HINDI_DISH_MAP[lower];
    } else {
      // Transliteration placeholder
      meal.nameHi = meal.nameEn;
    }
    logEntries.push(`Enriched Hindi translation for ${meal.nameEn}`);
  }

  // 3. Indian Dietary Sanity & Categorization Corrections (Phase 4 QA)
  const dishLower = meal.nameEn.toLowerCase();
  const isSweet = /gulab jamun|rasgulla|jalebi|kheer|halwa|laddu|barfi|rabri|peda|mysore pak/i.test(dishLower);

  if (isSweet && meal.category === 'nonveg') {
    meal.category = 'veg';
    logEntries.push(`FIXED: Corrected sweet dish '${meal.nameEn}' from non-veg to veg.`);
  }

  // Permitted meats verification for Indian context (Chicken, Mutton, Fish, Prawn, Egg)
  if (meal.category === 'nonveg') {
    const hasDisallowedMeat = /beef|pork|bacon|ham|turkey|veal/i.test(dishLower) || /beef|pork|turkey/i.test(meal.meat_type);
    if (hasDisallowedMeat) {
      logEntries.push(`REJECTED: Dish '${meal.nameEn}' contains disallowed meat type.`);
      continue; // Discard invalid meal
    }

    // Auto tag egg if non-veg is purely egg based
    if (/egg|anda|omelet|bhurji/i.test(dishLower) && !/chicken|mutton|fish|prawn/i.test(dishLower)) {
      if (!meal.tags.includes('egg')) meal.tags.push('egg');
    }
  }

  // 4. Macro Calculation & Caloric Balance Verification
  const p = meal.macros.protein;
  const c = meal.macros.carbohydrate;
  const f = meal.macros.fat;
  const calculatedKcal = Math.round((p * 4) + (c * 4) + (f * 9));

  const diff = Math.abs(meal.kcal - calculatedKcal);
  if (diff > 50 && calculatedKcal > 0) {
    logEntries.push(`Adjusted calorie count for ${meal.nameEn} from ${meal.kcal} to ${calculatedKcal} based on 4P+4C+9F`);
    meal.kcal = calculatedKcal;
  }

  // 5. Automated Poshan Tagging Engine
  const tagSet = new Set(meal.tags || []);

  // High Protein tag (25g+ protein as per Phase 4 standard)
  if (p >= 25) {
    tagSet.add('highProtein');
    logEntries.push(`Tagged as highProtein (${p}g protein)`);
  }

  // Low GI tag (High fiber, controlled carbs)
  if (meal.macros.fibre >= 6 && c <= 35) {
    tagSet.add('lowGi');
  }

  // Iron Rich tag
  if (/palak|spinach|rajma|chole|chana|beetroot|mooli|liver|methi|ragi|sarson/i.test(dishLower)) {
    tagSet.add('ironRich');
  }

  // Vegan & Jain categorization
  if (meal.category === 'veg') {
    const hasDairy = /paneer|dahi|curd|milk|ghee|butter|cheese|cream|khoya|chaas|buttermilk/i.test(dishLower);
    const hasEgg = tagSet.has('egg') || /egg|anda/i.test(dishLower);

    if (!hasDairy && !hasEgg && !meal.source.includes('dairy')) {
      tagSet.add('vegan');
    }

    const hasRootVeg = /potato|aloo|onion|pyaz|garlic|lahsun|ginger|adrak|carrot|gajar|radish|mooli/i.test(dishLower);
    if (!hasRootVeg && !hasEgg && (dishLower.includes('jain') || meal.time === 'lunch')) {
      // Only tag Jain if strictly verified or explicitly specified
      if (dishLower.includes('jain')) tagSet.add('jain');
    }
  }

  meal.tags = Array.from(tagSet);

  // 6. Subscription Tier Assignment
  // Premium: 25g+ protein, clinical support meals, or condition-specific cards
  // Free: standard everyday Indian staples
  if (tagSet.has('highProtein') || meal.source.includes('docx') || p >= 25) {
    meal.tier = 'premium';
  } else {
    meal.tier = meal.tier || 'free';
  }

  // 7. Note Generation (Bilingual default if empty)
  if (!meal.noteEn) {
    meal.noteEn = `${meal.nameEn} prepared in traditional ${meal.region} Indian style with balanced macros (${p}g protein, ${meal.macros.fibre}g fibre).`;
  }
  if (!meal.noteHi) {
    meal.noteHi = `${meal.nameHi} पारंपरिक ${meal.region === 'north' ? 'उत्तर' : meal.region === 'south' ? 'दक्षिण' : meal.region === 'east' ? 'पूर्व' : 'पश्चिम'} भारतीय शैली में तैयार, संतुलित पोषण के साथ।`;
  }

  // Build final Poshan MealPlanItem structure
  const finalMealCard = {
    id: meal.id,
    name: {
      en: meal.nameEn,
      hi: meal.nameHi
    },
    region: meal.region,
    time: meal.time,
    category: meal.category,
    tags: meal.tags,
    kcal: meal.kcal,
    macros: meal.macros,
    note: {
      en: meal.noteEn,
      hi: meal.noteHi
    },
    tier: meal.tier
  };

  if (meal.photo) {
    finalMealCard.photo = meal.photo;
  }

  validatedMeals.push({
    json: finalMealCard
  });

  auditLog.push({
    dish: meal.nameEn,
    logs: logEntries
  });
}

return validatedMeals;

// Aggregate results and prepare summary statistics for Poshan app & audit reports
const items = $input.all();
const meals = items.map(i => i.json);

// Deduplicate meals by ID
const uniqueMap = new Map();
for (const m of meals) {
  uniqueMap.set(m.id, m);
}
const uniqueMeals = Array.from(uniqueMap.values());

// Compute statistics matching Poshan Meal Library metrics
const stats = {
  totalMeals: uniqueMeals.length,
  vegetarian: uniqueMeals.filter(m => m.category === 'veg').length,
  nonVegetarian: uniqueMeals.filter(m => m.category === 'nonveg').length,
  highProtein: uniqueMeals.filter(m => m.tags.includes('highProtein')).length,
  vegan: uniqueMeals.filter(m => m.tags.includes('vegan')).length,
  lowGi: uniqueMeals.filter(m => m.tags.includes('lowGi')).length,
  ironRich: uniqueMeals.filter(m => m.tags.includes('ironRich')).length,
  regions: {
    north: uniqueMeals.filter(m => m.region === 'north').length,
    south: uniqueMeals.filter(m => m.region === 'south').length,
    east: uniqueMeals.filter(m => m.region === 'east').length,
    west: uniqueMeals.filter(m => m.region === 'west').length
  },
  tiers: {
    free: uniqueMeals.filter(m => m.tier === 'free').length,
    premium: uniqueMeals.filter(m => m.tier === 'premium').length
  }
};

return [{
  json: {
    status: 'success',
    timestamp: new Date().toISOString(),
    stats,
    count: uniqueMeals.length,
    meals: uniqueMeals
  }
}];
